// Static preview images for real PDFs, rendered from the PDF files
// themselves (pdftoppm at 120 DPI -> webp -> base64 data URIs).
//
// WHY base64 in code, not files under public/images/: the deploy
// pipeline available to this agent only accepts text files, so binary
// image files cannot be committed through it. The images therefore live
// in this module as data URIs. This module is loaded LAZILY (dynamic
// import in PdfCoverPreview), so these bytes do not bloat the main
// bundle - they are fetched only when a PDF preview is actually shown.
//
// To add a preview for a future real PDF: render its first pages to
// webp (pdftoppm -r 120), base64-encode them, and add one entry below
// keyed by a distinctive part of the PDF file name. Anything without
// an entry gets the styled placeholder card - never an iframe, never
// a fake file.

// Code 106 model-answers book - cover page (page 1).
const COVER_DIB_PART_1_CODE_106 =
  'data:image/webp;base64,';

// Code 106 model-answers book - table of contents (page 2).
const PAGE_2_DIB_PART_1_CODE_106 =
  'data:image/webp;base64,';

// Code 105 model-answers book (English version) - cover page (page 1).
const COVER_DIB_PART_1_CODE_105_ENGLISH =
  'data:image/webp;base64,';

// Code 105 model-answers book (English version) - table of contents (page 2).
const PAGE_2_DIB_PART_1_CODE_105_ENGLISH =
  'data:image/webp;base64,';

// Code 106 repeated-questions model-answers book (Bengali) - cover page (page 1).
const COVER_DIB_PART_1_CODE_106_REPEATED_BENGALI =
  'data:image/webp;base64,';

// Code 106 repeated-questions model-answers book (Bengali) - table of contents (page 2).
const PAGE_2_DIB_PART_1_CODE_106_REPEATED_BENGALI =
  'data:image/webp;base64,';

// Code 105 repeated-questions revision notes book, English version - cover page (page 1).
const COVER_DIB_PART_1_CODE_105_REPEATED_NOTES_ENGLISH =
  'data:image/webp;base64,';

// Code 105 repeated-questions revision notes book, English version - contents page (page 2).
const PAGE_2_DIB_PART_1_CODE_105_REPEATED_NOTES_ENGLISH =
  'data:image/webp;base64,';

const PDF_COVER_IMAGES: { match: string; images: string[] }[] = [
  {
    // Code 106 model-answers book (63 pages). The article copy and the
    // library copy are the same PDF uploaded twice, so one entry covers
    // both storage URLs.
    match: 'diploma-islamic-banking-part-i.pdf',
    images: [COVER_DIB_PART_1_CODE_106, PAGE_2_DIB_PART_1_CODE_106],
  },
  {
    // Code 105 model-answers book, English version (227 pages).
    // Attached to the article dib-part-1-code-105-business-communication-
    // model-answers-english; the match is the distinctive file name.
    match: 'dib-part-1-105-model-answers-english.pdf',
    images: [COVER_DIB_PART_1_CODE_105_ENGLISH, PAGE_2_DIB_PART_1_CODE_105_ENGLISH],
  },
  {
    // Code 106 repeated-questions model-answers book, Bengali version
    // (137 pages: 51 questions that appeared 3+ times + 31 repeated
    // short notes). The match is the distinctive file name.
    match: 'dib-part-1-106-repeated-51-model-answers-bengali.pdf',
    images: [COVER_DIB_PART_1_CODE_106_REPEATED_BENGALI, PAGE_2_DIB_PART_1_CODE_106_REPEATED_BENGALI],
  },
  {
    // Code 105 repeated-questions revision notes book, English version
    // (23 pages: 13 main topics + 2 short notes that appeared 3+ times,
    // May 2023 - May 2026). The match is the distinctive file name.
    match: 'dib-part-1-105-repeated-questions-notes-english.pdf',
    images: [COVER_DIB_PART_1_CODE_105_REPEATED_NOTES_ENGLISH, PAGE_2_DIB_PART_1_CODE_105_REPEATED_NOTES_ENGLISH],
  },
];

// Cover/first-page images for a PDF, or [] when none was generated.
// Callers must render the styled placeholder in that case.
export function getPdfCoverImages(pdfUrl?: string | null): string[] {
  if (!pdfUrl) return [];
  const entry = PDF_COVER_IMAGES.find((e) => pdfUrl.includes(e.match));
  return entry ? entry.images : [];
}
